import json,pathlib,collections,re,shutil
from PIL import Image,ImageChops,ImageStat
R=pathlib.Path(__file__).resolve().parent
products=json.loads((R/'data/products.json').read_text())
photos=json.loads((R/'data/photos.json').read_text())
# Retain independent photographs, discard resized copies.
kept=[];tiny=collections.defaultdict(list)
for m in photos:
 if m['status']!='downloaded':continue
 im=Image.open(R/m['path']).convert('RGB').resize((64,64))
 if any(sum(ImageStat.Stat(ImageChops.difference(im,t)).mean)/3<7 for t in tiny[m['product_id']]):
  (R/m['path']).unlink();continue
 tiny[m['product_id']].append(im);kept.append(m)
photos=kept
(R/'data/photos.json').write_text(json.dumps(photos,ensure_ascii=False,indent=2))
spec={1:[('Размер листа','35,8 × 68 мм'),('Плотность','14 г/м²')],2:[('Размер листа','35,8 × 68 мм'),('Плотность','18,5 г/м²'),('Закрывание','Магнитное')],3:[('Размер листа у продавца','28 × 70 мм'),('Плотность','18,5 г/м²')],4:[],5:[('Размер листа','35,8 × 68 мм'),('Плотность','18,5 г/м²')],6:[],7:[('Размер листа','35,8 × 68 мм'),('Плотность','21 г/м²'),('Закрывание','Магнитное')],8:[('Размер листа','35,8 × 68 мм'),('Плотность','21 г/м²')],9:[('Плотность, предварительно','14 г/м²')],10:[],11:[('Размер листа','35,8 × 68 мм'),('Плотность','18,5 г/м²'),('Материал по источнику','Неотбелённая конопляная бумага')],12:[],13:[('Размер листа','35,8 × 68 мм'),('Плотность','12 г/м²'),('Закрывание','Магнитное')],14:[('Размер листа','35,8 × 68 мм'),('Плотность','12 г/м²')],15:[('Размер листа у продавца','28 × 70 мм'),('Плотность','12 г/м²')],16:[('Размер листа','44 × 78 мм'),('Плотность','12 г/м²')],17:[('Длина рулона','5 м'),('Ширина по источнику','44 мм')],18:[],19:[],20:[],21:[('Диаметр по исходной таблице','5,3 мм'),('Длина по сайту GIZEH','15 мм')],22:[('Диаметр','8 мм'),('Конструкция по продавцу','Трёхкамерная, с активированным углём')],23:[('Диаметр','8 мм')]}
notes={1:'В таблице не указана серия BLACK и магнитное закрывание. Найдена близкая модель BLACK Extra Fine Magnet 100; её фотографии — возможное соответствие, не подтверждение вашей упаковки.',3:'Источники расходятся по точным размерам Extra Slim: 28 × 70 мм против 27,8 × 68 мм. Нужна маркировка реальной упаковки.',6:'Недостаточно данных для выбора серии. Найденный образец — King Size Slim Extra Fine 34 (оранжевый); магнитное закрывание из таблицы для этого образца не подтверждено. Не переносить характеристики образца на вашу позицию.',9:'Продавец указал 14 g/m2 в поле Size: это плотность, а не линейный размер. Источник вторичный; геометрия листа не подтверждена.',10:'Найдена модель по названию и фотографии. Динамическое описание страницы не выгружено; материал, плотность и геометрия не подтверждены в сохранённом тексте.',12:'Найдена модель по названию и фотографии. Динамическое описание страницы не выгружено; материал, плотность и геометрия не подтверждены в сохранённом тексте.',15:'Размеры 28 × 70 мм указаны продавцом; точная маркировка вашей партии не проверена.',18:'Таблица: King Size, 33 листа. Найден King Size Slim на 33 листа, 110 × 44 мм, 13,8 г/м²; одновременно встречается серия King Size на 34 листа. Фотография Slim — только кандидат, не подтверждение модели из таблицы.',19:'Название Original 50 найдено в каталоге продавца. Фото миниатюрное; точные размеры и плотность не установлены.',20:'Найдено название Slim 66 и фотография. Геометрия и плотность не установлены.',21:'На сайте GIZEH название содержит 5mm, описание — 5mm, а поле Diameter — 6 mm; таблица содержит 5,3 мм. Диаметр не считать окончательно подтверждённым до проверки упаковки.',27:'Уточнение конструкции: 12 мм фильтрующей части + 5 мм углубления = 17 мм Recess. Это не 17 мм сплошного фильтрующего материала.'}
for p in products:
 k=p['id'];p['notes']=notes.get(k,'Совпадение модели по открытым источникам не подтверждает внешний вид и подлинность вашей партии. Для окончательной сверки нужны фото упаковки и EAN.')
 p['status']='Артикул и характеристики совпали' if k>=24 else ('Требуется уточнение модели' if k in [1,6,18,21] else 'Предварительное соответствие по названию')
 p['extra_specs']=spec.get(k,[])
 if 24<=k<=30:
  p['extra_specs']=[('Длина гильзы','84 мм'),('Диаметр по поставщику','7,0 мм' if k in [28,29] else '8,1 мм'),('Длина фильтра',{24:'15 мм',25:'15 мм',26:'24 мм',27:'17 мм (12 + 5)',28:'17 мм',29:'24 мм',30:'15 мм'}[k])]
 if k>=31:p['extra_specs']=[('Размер листа','37 × 70 мм'),('Плотность','14,5 г/м²' if k==31 else '14,0 г/м²'),('Буклетов в блоке','50'),('Листов в буклете','50'),('Листов в блоке, расчёт','2500')]
 src=R/f'sources/product-{k:02d}.json';d=json.loads(src.read_text()) if src.exists() else {}
 p['source_url']=d.get('source_url','');p['source_title']=d.get('title','Источник не найден')
 p['photos']=[m for m in photos if m['product_id']==k]
 folder=R/f'catalog/{k:02d}';folder.mkdir(exist_ok=True)
 name=f"{p['brand']} — {p['model']}"
 table=[('Тип',p['type']),('Модель из таблицы',p['model']),('Особенности из таблицы',p['features'] or 'Не указаны'),('Содержимое одной упаковки',f"{p['per_package']} {p['unit']}"),('Артикул поставщика',p['supplier_article'] or 'Не указан')]+p['extra_specs']
 text=f"# {k:02d}. {name}\n\n[Все товары](../../README.md) · [Комплектация](quantities.md) · [Фотографии](photos.md)\n\n**Статус:** {p['status']}.\n\n{p['notes']}\n\n## Технические данные\n\n| Поле | Значение |\n|---|---|\n"+''.join(f'| {a} | {b} |\n' for a,b in table)
 text+='\nПоля «из таблицы» получены из приложенного файла. Дополнительные характеристики приведены по ссылке ниже и не являются результатом физических измерений.\n'
 text+=f"\n## Источник\n\n[{p['source_title']}]({p['source_url']}) — просмотрено 24.11.2026. Сведения одного источника предварительные.\n"
 (folder/'passport.md').write_text(text)
 q=f'# Комплектация — {name}\n\n[Паспорт](passport.md) · [Фотографии](photos.md)\n\nКоличество упаковок не равно количеству листов, фильтров или гильз. Варианты ниже взяты из таблицы; это расчёт содержимого, не подтверждение наличия готового набора.\n\n| Упаковок | Содержимое |\n|---|---|\n'
 for n in p['variants']:
  total=n*p['per_package'];q+=f"| {n} | {total} {p['unit']}"+(f' = {total*50} листов' if k>=31 else '')+' |\n'
 (folder/'quantities.md').write_text(q)
 gallery=f'# Документальные фотографии — {name}\n\n[Паспорт](passport.md) · [Комплектация](quantities.md)\n\nЭто изображения внешних источников, не фотографии вашей партии. Фоны оставлены исходными: искусственные офисные или природные сцены не создавались. Отдельная страница на каждую фотографию.\n\n'
 if not p['photos']:gallery+='Подходящих фотографий пока нет.\n'
 for n,m in enumerate(p['photos'],1):
  file=f'photo-{n:02d}.md';gallery+=f'- [Изображение {n:02d}]({file})\n'
  (folder/file).write_text(f"# {name} — изображение {n:02d}\n\n[Паспорт](passport.md) · [Все фотографии](photos.md)\n\n{p['notes']}\n\n![Документальное изображение {name}](../../{m['path']})\n\n[Страница источника]({m['page']}) · [Оригинальный файл]({m['url']})\n\nРазмер сохранённого изображения: {m['width']} × {m['height']} px. Изображение не подтверждает комплект из 3 или 5 упаковок. Права на фотографию принадлежат правообладателю; разрешение на коммерческое использование не проверено.\n")
 (folder/'photos.md').write_text(gallery)
(R/'data/catalog.json').write_text(json.dumps(products,ensure_ascii=False,indent=2))
count=len(photos)
index=f'# Технический каталог товаров\n\n33 позиции · 91 вариант комплектации · {count} документальных изображений\n\nНейтральный справочный каталог по приложенной таблице. Не рекламные карточки и не готовый комплект для маркетплейсов. Дата проверки: **24 ноября 2026 года**.\n\n## Как читать\n\nКаждый товар разделён на паспорт, комплектацию и галерею; каждая фотография открывается отдельно. Количество упаковок и содержимое показаны раздельно. Закупочные цены, объёмы закупки и накладные исключены.\n\n## Ограничения проверки\n\n- Без фотографий реальных упаковок нельзя окончательно идентифицировать партию.\n- У позиций 1, 6, 18 и 21 есть неоднозначности модели или размера. Подробности в паспортах.\n- 223 изображения были ориентиром для прежнего рекламного формата. В документальном каталоге количество определяется найденными фотографиями; недостающие ракурсы и наборы не выдуманы.\n- Точность вторичных источников и права на коммерческое использование фото не гарантированы.\n\n## Товары\n\n| № | Модель | В упаковке | Фото | Проверка |\n|---|---|---|---|---|\n'
for p in products:
 k=p['id'];index+=f"| {k:02d} | [{p['brand']} {p['model']}](catalog/{k:02d}/passport.md) | {p['per_package']} {p['unit']} | [{len(p['photos'])}](catalog/{k:02d}/photos.md) | {p['status']} |\n"
index+='\n## Структура проекта\n\n- `catalog/` — отдельные Markdown-страницы.\n- `assets/` — найденные документальные фотографии.\n- `data/products.json` — данные таблицы без закупочных сведений.\n- `data/catalog.json` — характеристики, статусы, источники.\n- `data/photos.json` — происхождение изображений и контрольные суммы.\n- `RIGHTS.md` — ограничения использования изображений.\n'
(R/'README.md').write_text(index)
(R/'RIGHTS.md').write_text('# Права и происхождение\n\nФотографии взяты из открытых сайтов производителей и продавцов для документального сопоставления товаров. Доступность файла не означает свободную лицензию. Лицензии и разрешения на коммерческое использование не проверялись. Авторство не присваивается; первоисточник указан рядом с каждой фотографией и в `data/photos.json`. При поступлении требования правообладателя соответствующее изображение следует удалить.\n\nФотографии не изменялись содержательно, не помещались в искусственные сцены и не использовались для создания вымышленных наборов. Выполнены техническое преобразование в JPEG и уменьшение до 1600 px для хранения. Данные сторонних источников не подтверждают подлинность конкретной партии.\n')
print('Built',len(products),'products,',count,'photos,',len(list((R/'catalog').rglob('*.md'))),'Markdown pages')